// EVIDENCE_FEED_URLS: 쉼표로 구분한 RSS 주소. 비어 있으면 0건.
const raw = String($env.EVIDENCE_FEED_URLS ?? '');
return raw.split(',').map((s) => s.trim()).filter((s) => s !== '').map((url) => ({ json: { url } }));

// 근거 후보 키워드 매칭. n8n "Match Pledges" Code 노드에 그대로 들어가므로 import 없이, 지울 수 있는 타입만 쓴다.

function normalizeText(s        )         {
  return s.replace(/\s+/g, ' ').trim().toLowerCase();
}

// 서울 기준 날짜(YYYY-MM-DD). 읽을 수 없으면 null.
function seoulDate(s                    )                {
  if (!s) return null;
  const t = Date.parse(s);
  if (Number.isNaN(t)) return null;
  return new Date(t + 9 * 3600 * 1000).toISOString().slice(0, 10);
}

/** 공약 키워드가 기사 제목·요약에 minHits 개 이상 나오면 (공약, 기사) 한 쌍을 후보로 낸다. */
function matchItems(
  items            ,
  pledges                  ,
  opts                       = {},
)                 {
  const minHits = opts.minHits ?? 1;
  const seen = new Set        ();
  const rows                 = [];
  for (const it of items) {
    const url = (it.link ?? '').trim();
    if (!/^https?:\/\//i.test(url)) continue;
    const hay = normalizeText(`${it.title ?? ''} ${it.contentSnippet ?? ''}`);
    for (const p of pledges) {
      const keywords = (p.keywords ?? []).filter((k) => normalizeText(k) !== '');
      if (keywords.length === 0) continue;
      const matched = keywords.filter((k) => hay.includes(normalizeText(k)));
      if (matched.length === 0 || matched.length < minHits) continue;
      const key = `${p.id}\u0000${url}`;
      if (seen.has(key)) continue;
      seen.add(key);
      rows.push({
        pledge_id: p.id,
        title: (it.title ?? '').trim(),
        url,
        published_at: seoulDate(it.pubDate),
        source: it.source,
        matched_keywords: matched,
        score: Math.round((matched.length / keywords.length) * 100) / 100,
      });
    }
  }
  return rows.sort((a, b) =>
    a.pledge_id !== b.pledge_id ? (a.pledge_id < b.pledge_id ? -1 : 1) : a.url < b.url ? -1 : a.url > b.url ? 1 : 0,
  );
}

const pledges = $('Load Pledges')
  .all()
  .map((i) => ({ id: String(i.json.id ?? ''), keywords: Array.isArray(i.json.keywords) ? i.json.keywords.map(String) : [] }))
  .filter((p) => p.id !== '');
const feeds = $('Feed URLs').all();
function hostOf(u) {
  try {
    return new URL(String(u)).hostname;
  } catch {
    return '';
  }
}
function feedOf(it) {
  const pi = Array.isArray(it.pairedItem) ? it.pairedItem[0] : it.pairedItem;
  const idx = pi && typeof pi.item === 'number' ? pi.item : 0;
  return feeds[idx] ? feeds[idx].json.url : '';
}
const items = $input.all().map((it) => {
  const j = it.json;
  const link = typeof j.link === 'string' ? j.link : '';
  return {
    title: typeof j.title === 'string' ? j.title : '',
    link,
    pubDate: typeof j.isoDate === 'string' ? j.isoDate : typeof j.pubDate === 'string' ? j.pubDate : undefined,
    contentSnippet: typeof j.contentSnippet === 'string' ? j.contentSnippet : undefined,
    source: hostOf(feedOf(it)) || hostOf(link) || 'rss',
  };
});
const rows = matchItems(items, pledges);
return rows.length === 0 ? [] : [{ json: { rows } }];
